class Solution {
public:
    int n;
    vector<int> dp;
    const int INF = 1e9;

    int rec(int rem,vector<int>&coins){
        //prunning if rem is negative then invalid
        if(rem<0) 
            return INF;
        //base case check
        if(!rem){
            return 0;
        }

        //cache check
        if(dp[rem]!=-1){
            return dp[rem];
        }
        //transition
        int ans = INF;
        for(int i=0;i<n;i++){
            ans=min(ans,1+rec(rem-coins[i],coins));
        }
        dp[rem]=ans;

        return ans;
    }
    int coinChange(vector<int>& coins, int amount) {
        n=coins.size();

        dp.assign(amount+1,-1);

        int ans=rec(amount,coins);
        if(ans!=INF)
            return ans;
        return -1;
    }
};

class Solution {
public:
    int tar;
    vector<vector<int>> dp;

    int rec(int i, int s, vector<int>& c){
        //pruning
        if(s > tar || i == (int)c.size())
            return 0;
        //base case
        if(s == tar)
            return 1;
        //cache check
        if(dp[i][s] != -1)
            return dp[i][s];
        //transition
        int ans = 0;
        ans += rec(i+1, s, c);       // don't use coin i anymore
        ans += rec(i, s+c[i], c);    // use coin i again (unlimited supply)

        //save and return
        dp[i][s] = ans;
        return dp[i][s];
    }

    int change(int amount, vector<int>& coins){
        tar = amount;
        dp.assign(coins.size()+1, vector<int>(tar+1, -1));

        return rec(0, 0, coins);
    }
};

class Solution {
