/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */

class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {

        if(root== NULL){
            return NULL;
        }

        queue<TreeNode*> q;
        q.push(root);

        while(!q.empty()){

            TreeNode* node=q.front();
            q.pop();
            //swap node
            TreeNode* temp=node->left;
            node->left=node->right;
            node->right=temp;

            if(node->left!=NULL)
                q.push(node->left);
            if(node->right!=NULL)
                q.push(node->right);
        }
        return root;

    }
};

class Solution {
public:
    void islandsAndTreasure(vector<vector<int>>& grid) {
        int row=grid.size();
        int col=grid[0].size();

        int INF=2147483647;

        queue<pair<int,int>>q;

        for(int i=0;i<row;i++){
            for(int j=0;j<col;j++){
                if(grid[i][j]==0)
                q.push({i,j});
            }
        }

        int dist=0;
        int dr[]={1,-1,0,0};
        int dc[]={0,0,1,-1};

        while(!q.empty()){
            int k=q.size();
            for(int x=0;x<k;x++){//msbfs
                int r=q.front().first;
                int c=q.front().second;

                q.pop();

                for(int i=0;i<4;i++){
                    int nr=r+dr[i];
                    int nc=c+dc[i];

                    if(nr>=0&&nr<row&&nc>=0&&nc<col&&grid[nr][nc]==INF){
