class Solution {
public:
    int characterReplacement(string s, int k) {
        int left = 0;
        int n = s.size();
        int maxf = 0;
        int ans = 0;
        vector<int> freq(26, 0);

        for (int right = 0; right < n; right++) {
            freq[s[right] - 'A']++;
            maxf = max(maxf, freq[s[right] - 'A']);

            while ((right - left + 1) - maxf > k) {
                freq[s[left] - 'A']--;
                left++;
            }

            ans = max(ans, right - left + 1);
        }

        return ans;
    }
};

