class Solution {
public:
    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
        int row=heights.size();
        int col=heights[0].size();

        vector<vector<bool>>pac(row,vector<bool>(col,false));
        vector<vector<bool>>at(row,vector<bool>(col,false));
        //top
        for(int c=0;c<col;c++){
            dfs(heights,pac,0,c,row,col);
        }
        //right
        for(int r=0;r<row;r++){
            dfs(heights,at,r,col-1,row,col);
        }
        //bottom
        for(int c=0;c<col;c++)
            dfs(heights,at,row-1,c,row,col);
        //left
        for(int r=0;r<row;r++){
            dfs(heights,pac,r,0,row,col);
        }

        vector<vector<int>>list;

        for(int r=0;r<row;r++){
            for(int c=0;c<col;c++){
                if(pac[r][c]&&at[r][c])
                    list.push_back({r,c});
            }
        }
        return list;
    }
    void dfs(vector<vector<int>>& heights, vector<vector<bool>>& oc, int r, int c,int row, int col){
        oc[r][c]=true;

        int dr[]={1,-1,0,0};
        int dc[]={0,0,-1,1};
        for(int i=0;i<4;i++){
            int nr=r+dr[i];
            int nc=c+dc[i];

            if(nc<0 || nc>=col || nr<0 || nr>=row){
                continue;
            }
            if(oc[nr][nc])
                continue;
            if(heights[r][c]>heights[nr][nc])
                continue;
            dfs(heights,oc,nr,nc,row,col);
        }
    }
};

class Solution {
public:
    vector<vector<int>>dp;
    int sum=0;
    int n;
    int rec(int i,int s,vector<int>&nums){
        //prunning
        if(s>sum)
            return false;
        //basecase
        if(i==n){
            if(s==sum)
                return true;
            return false;
        }
        //cache chek
        if(dp[i][s]!=-1)
            return dp[i][s];
        //transition
        int ans=0;
        if(rec(i+1,s,nums))
            ans=1;
        if(rec(i+1,s+nums[i],nums))
            ans=1;
        //save and return
        dp[i][s]=ans;
        return dp[i][s];

    }
    bool canPartition(vector<int>& nums) {

        for(auto x:nums)
            sum+=x;
        if(sum%2)
            return false;
        n=nums.size();
        sum/=2;
        dp.assign(n, vector<int>(sum + 1, -1));

        int ans=rec(0,0,nums);
        return ans;

    }
};

class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        if(s1.size()>s2.size()){
            return false;
        }
        vector<int>freq(128,0);
        vector<int>win(128,0);
        int k=s1.size();
        for (int i = 0; i < k; i++) {
            freq[s1[i]]++;
            win[s2[i]]++;
        }
        if (win == freq) return true;
        //window size and condition
        //if condition remains true size can be expanded atmost k
        //when size is k and condition is true answer is true
        int n=s2.size();
        int left = 0, right = 0;
        for (int right = k; right < s2.size(); right++) {
            win[s2[right]]++;          
            win[s2[left]]--;
            left++;

            if (win == freq) return true;
        }
        return false;

    }
};

class Solution {
public:
    string S,P;
    vector<vector<int>>dp;
    int n,m;
    int rec(int i,int j){
    if(j==m) return i==n;                                      // only j gives a verdict
    if(dp[i][j]!=-1) return dp[i][j];

    if(j+1<m && P[j+1]=='*') return dp[i][j] = rec(i,j+1);     // starred group → defer to '*'

    int ans=0;
    if(i<n && (S[i]==P[j]||P[j]=='.')){                        // mandatory char
        ans=rec(i+1,j+1);
    } else if(P[j]=='*'){                                      // on the '*'
        if(j-1>=0){
            ans=rec(i,j+1);                                    // zero more
            if(i<n && (P[j-1]==S[i]||P[j-1]=='.'))
                ans = ans || rec(i+1,j);                       // one more
        }
    }
    return dp[i][j]=ans;
}
    bool isMatch(string s, string p) {
        S=s;
        P=p;
        dp.assign(21,vector<int>(21,-1));

        n=s.size();
        m=p.size();

        return rec(0,0);

    }
};

class Solution {
public:
    int orangesRotting(vector<vector<int>>& grid) {
        int row=grid.size();
        int col=grid[0].size();

        queue<pair<int,int>>q;

        int fresh=0;
        int min=0;
        for(int i=0;i<row;i++){
            for(int j=0;j<col;j++){
                if(grid[i][j]==2){
                    q.push({i,j});
                }
                else if(grid[i][j]==1){
                    fresh++;
                }
            }
        }


        int dr[]={1,-1,0,0};
        int dc[]={0,0,1,-1};

        while(fresh>0 && !q.empty()){
            int k=q.size();
            for(int i=0;i<k;i++){
                int r=q.front().first;
                int c=q.front().second;
                q.pop();

                for(int j=0;j<4;j++){        // renamed i -> j
                    int nr=r+dr[j];
                    int nc=c+dc[j];
                    if(nr>=0 && nr<row && nc>=0 && nc<col && grid[nr][nc]==1){
                        grid[nr][nc]=2;
                        fresh--;
                        q.push({nr,nc});
                    }
                }
            }
            min++;
        }
        return fresh==0 ? min : -1;}
};

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int n=matrix.size();
        int m=matrix[0].size();
        //i*n+j flattens
        //t=i*n+j
        //i=t/n, j=t%n
        //just move t from 0 to m*n-1
        return bin(0,m*n-1,matrix,target);
    }
    bool check(int mid,vector<vector<int>>& matrix,int target){
        int n=matrix[0].size();
        int i=mid/n;
        int j=mid%n;

        return matrix[i][j]>=target;
    }

    int bin(int lo,int hi,vector<vector<int>>& matrix,int target){
        while(lo<hi){
            int mid = lo + (hi-lo)/2;
            if(check(mid,matrix,target))
                hi=mid;
            else
                lo=mid+1;
        }
        int n=matrix[0].size();
        int i=lo/n;
        int j=lo%n;

        if(matrix[i][j]==target)
            return true;
        return false;
    }
};

